        /// <summary>从 ConfigKit 生成的 .tsv 文本填充数据（Editor 导入器用；第一行是字段名）。</summary>
        public void LoadFromTsv(string text)
        {
            rows.Clear();

            if (string.IsNullOrEmpty(text))
            {
                RebuildIndex();
                return;
            }

            string[] lines = text.Replace("\r\n", "\n").Replace('\r', '\n').Split('\n');
            string[] header = lines[0].Split('\t');  // 第一行是字段名

            for (int i = 1; i < lines.Length; i++)  // 从第 2 行开始（第 1 行是字段名）
            {
                if (lines[i].Length == 0)
                {
                    continue;
                }

                string[] cells = lines[i].Split('\t');
                Config_Level row = new Config_Level();
                row.id = ParseInt(Cell(cells, header, "id"));
                row.sceneName = Unescape(Cell(cells, header, "sceneName"));
                row.displayName = Unescape(Cell(cells, header, "displayName"));
                row.monsterWaves = ParseInt(Cell(cells, header, "monsterWaves"));
                row.timeLimitSeconds = ParseInt(Cell(cells, header, "timeLimitSeconds"));
                row.bossSkillId = ParseInt(Cell(cells, header, "bossSkillId"));

                rows.Add(row);
            }

            RebuildIndex();
        }

        /// <summary>按字段名取单元格（按名字对列，所以调换列顺序不会错位）。</summary>
        private static string Cell(string[] cells, string[] header, string name)
