        }

        /// <summary>解析 bool（`1` / `true`）。</summary>
        private static bool ParseBool(string text)
        {
            return text == "1" || string.Equals(text, "true", System.StringComparison.OrdinalIgnoreCase);
        }

        /// <summary>解析逗号分隔的整数数组。</summary>
        private static int[] ParseIntArray(string text)
        {
            if (string.IsNullOrEmpty(text))
            {
                return new int[0];
            }

            string[] parts = text.Split(',');
            int[] result = new int[parts.Length];

            for (int i = 0; i < parts.Length; i++)
            {
                result[i] = ParseInt(parts[i].Trim());
            }

            return result;
        }

        /// <summary>还原 TSV 的转义。</summary>
        private static string Unescape(string text)
        {
            if (string.IsNullOrEmpty(text) || text.IndexOf('\\') < 0)
            {
                return text;
            }

            System.Text.StringBuilder builder = new System.Text.StringBuilder(text.Length);

            for (int i = 0; i < text.Length; i++)
            {
                if (text[i] != '\\' || i + 1 >= text.Length)
                {
                    builder.Append(text[i]);
                    continue;
                }

                i++;

                switch (text[i])
                {
                    case 't': builder.Append('\t'); break;
                    case 'r': builder.Append('\r'); break;
                    case 'n': builder.Append('\n'); break;
                    case '\\': builder.Append('\\'); break;
                    default: builder.Append(text[i]); break;
                }
            }

            return builder.ToString();
        }
